            aIngress ^= (RotL64(aMagmaLaneA[((aIndex + 11638U)) & S_BLOCK1], 60U) ^ RotL64(aLightningLaneD[((aIndex + 12478U)) & S_BLOCK1], 13U));
            aIngress = TwistMix64::DiffuseC(((aIngress ^ aDomainWordIngress) ^ aNonceWordF));
