            aOrbiterB = RotL64((aOrbiterB * 0x9CF4D7B7E9EB33AFULL), 41U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterI) + 0x26849BBFAE367867ULL) + aOrbiterUpdateSaltF[(((255U - aIndex) + 101U)) & S_SALT1];
