            //
            aIngress = (RotL64(aLightningLaneA[((aIndex + 5783U)) & S_BLOCK1], 12U) ^ RotL64(aHeartLaneC[((aIndex + 8963U)) & S_BLOCK1], 57U));
            aIngress ^= (RotL64(aEarthLaneA[((aIndex + 8328U)) & S_BLOCK1], 37U) ^ RotL64(aEarthLaneC[((S_BLOCK1 - aIndex + 10736U)) & S_BLOCK1], 21U));
