            aCross ^= RotL64(pCrossLaneB[((aIndex + 6847U)) & S_BLOCK1], 12U);
            aCross = TwistMix64::DiffuseB((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 5U) + RotL64(aCarry, 22U)) + (RotL64(aIngress, 41U) ^ RotL64(aCross, 53U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterG = ((aWandererK + RotL64(aPrevious, 41U)) + RotL64(aCarry, 41U)) + 0x35894B8579CA9037ULL;
            aOrbiterD = ((aWandererJ + RotL64(aScatter, 11U)) + 0x9B47A8555ADC0649ULL) + aTwistOrbiterAssignSaltD[(((255U - aIndex) + 4U)) & S_SALT1];
