            //
            aOrbiterG = (aWandererK + RotL64(aPrevious, 19U)) + 0x189DDB95086CA3D2ULL;
            aOrbiterA = (((aWandererC + RotL64(aCross, 14U)) + RotL64(aCarry, 5U)) + 0xD53D29FA7827E423ULL) + aTwistOrbiterAssignSaltF[(((255U - aIndex) + 133U)) & S_SALT1];
            aOrbiterK = (aWandererI + RotL64(aIngress, 57U)) + 0x5A8721A301E7C934ULL;
            aOrbiterF = (aWandererD + RotL64(aScatter, 27U)) + 0xEAE8EB273948D4DBULL;
            aOrbiterB = (aWandererA + RotL64(aIngress, 3U)) + 0xC5C42C5DC868BAD7ULL;
