            aOrbiterF = (aOrbiterF + aOrbiterK) + 0xB5B20EBE55C68B8FULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterF) ^ 0x66395B4E4C769B09ULL) ^ aKeyRotateAOrbiterUpdateSaltC[((aIndex + 26U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x8D1969F963AF1E21ULL), 19U);
            //
            aIngress = aOrbiterK ^ RotL64(aOrbiterC, 12U);
