            //
            aWandererC = aWandererC ^ (((RotL64(aScatter, 21U) + RotL64(aOrbiterG, 12U)) + aOrbiterH) + aKeyRotateAWandererUpdateSaltF[(((255U - aIndex) + 37U)) & S_SALT1]);
            aWandererE = aWandererE + (((RotL64(aCross, 51U) + aOrbiterK) + RotL64(aOrbiterC, 41U)) + RotL64(aCarry, 13U));
