            aCross ^= (RotL64(aKeyRowReadB[(((2047U - aIndex) + 30520U)) & W_KEY1], 48U) ^ RotL64(aMagmaLaneC[((S_BLOCK1 - aIndex + 24824U)) & S_BLOCK1], 13U));
            aCross = TwistMix64::DiffuseA((aCross ^ aKeyRotateADomainWordCross));
