            aScatter = (RotL64(aIngress, 43U) + RotL64(aCarry, 11U)) ^ (RotL64(aCross, 58U) + RotL64(aPrevious, 29U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
