            aOrbiterC = (aWandererI + RotL64(aScatter, 37U)) + 0xE276D4EF5EFC82AFULL;
            aOrbiterD = (aWandererB + RotL64(aIngress, 5U)) + 0x90984A847DB685C9ULL;
            aOrbiterE = ((aWandererJ + RotL64(aCross, 12U)) + RotL64(aCarry, 21U)) + 0x4A5D409A55949A5DULL;
            aOrbiterG = (((aWandererG + RotL64(aPrevious, 27U)) + RotL64(aCarry, 3U)) + 0x8523077D686FCAE0ULL) + aKeyRotateAOrbiterAssignSaltD[((aIndex + 108U)) & S_SALT1];
            aOrbiterF = (((aWandererA + RotL64(aIngress, 43U)) + RotL64(aCarry, 37U)) + 0xF9C4496CC8683CF1ULL) + aKeyRotateAOrbiterAssignSaltC[((aIndex + 9U)) & S_SALT1];
            aOrbiterH = (aWandererF + RotL64(aScatter, 51U)) + 0x9CD50498C167C0C8ULL;
            aOrbiterK = (aWandererE + RotL64(aPrevious, 19U)) + 0xABF01FD7DDC52A45ULL;
            //
            aOrbiterC = ((aOrbiterC + aOrbiterD) + 0x05B3474A2219101CULL) + aKeyRotateAOrbiterUpdateSaltD[(((255U - aIndex) + 28U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterC) ^ 0x3AA88D15DB533DE9ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x3E60D8BF883F3E7BULL), 47U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0xE6A2B7E42761A1C4ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterE) ^ 0x51CBCAE2AADB27AAULL) ^ aKeyRotateAOrbiterUpdateSaltF[(((255U - aIndex) + 219U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x08783166B711EDB1ULL), 57U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterE) + 0x768310E0EE9AF0BBULL) + aKeyRotateAOrbiterUpdateSaltA[(((255U - aIndex) + 246U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterD) ^ 0xA7181235608B2096ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x399AA4530D94B9B3ULL), 21U);
