            aOrbiterH = (aOrbiterH + aOrbiterK) + 0x230376764FD8F5A2ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterH) ^ 0xF0A4DB8DED466414ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xD2844DC1035F4CD1ULL), 41U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterF) + 0xA073604BACCEF325ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterG) ^ 0x6442FB48F93D3090ULL) ^ aKeyRotateAOrbiterUpdateSaltB[((aIndex + 95U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x14052C879E8D2253ULL), 29U);
