            aOrbiterK = (aOrbiterK + aOrbiterC) + 0x08BD843DFAC1224EULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterK) ^ 0x6EC37E1DAA6267F6ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x7C7E4F182B015E3BULL), 11U);
            //
            aIngress = aOrbiterK ^ RotL64(aOrbiterE, 57U);
