            aWandererJ = aWandererJ + (((RotL64(aPrevious, 47U) + RotL64(aOrbiterK, 35U)) + aOrbiterD) + RotL64(aCarry, 47U));
            aWandererI = aWandererI ^ ((RotL64(aScatter, 13U) + RotL64(aOrbiterE, 11U)) + aOrbiterC);
