            aWandererB = aWandererB ^ (((RotL64(aScatter, 41U) + RotL64(aOrbiterH, 28U)) + aOrbiterK) + aKeyRotateAWandererUpdateSaltB[(((255U - aIndex) + 177U)) & S_SALT1]);
