            //
            aOrbiterJ = (aOrbiterJ + aOrbiterG) + 0x8EDC4812C6EAC7C6ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterJ) ^ 0x97E45D096E20E05DULL;
            aOrbiterH = RotL64((aOrbiterH * 0x45B885AE23CFEB65ULL), 53U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterH) + 0xE68FCE18A7C06CFCULL;
