            //
            aOrbiterC = ((aOrbiterC + aOrbiterB) + 0x184E866CB65A6B13ULL) + aKeyRotateAOrbiterUpdateSaltC[(((255U - aIndex) + 83U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterC) ^ 0xF89A72D5453744C5ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xE789990289916795ULL), 43U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterF) + 0xE364ACAF05D7B74EULL;
