            //
            aOrbiterE = ((aOrbiterE + aOrbiterD) + 0x6B0D8389EF57E9B8ULL) + aKeyRotateBOrbiterUpdateSaltF[((aIndex + 237U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterE) ^ 0x62D9D0CD86F8084EULL;
            aOrbiterH = RotL64((aOrbiterH * 0xCA7A1FDDB0C7E8B3ULL), 19U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterI) + 0x0A81D024CCDAD232ULL) + aKeyRotateBOrbiterUpdateSaltE[((aIndex + 222U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterJ) ^ 0x4B1193066A8128E6ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x75EE4966936C0519ULL), 57U);
